/** ShahkotPK v11.0.1 — safe installer for global public runtime. */
if(!function_exists('sk1101_install_public_runtime')){
function sk1101_install_public_runtime(): array {$root=dirname(__DIR__);$bootstrap=$root.'/app/bootstrap.php';$marker='SHAHKOTPK_PUBLIC_RUNTIME_V1101_BOOTSTRAP';if(!is_file($bootstrap))return ['ok'=>false,'status'=>'bootstrap_missing','message'=>'app/bootstrap.php not found.'];$src=@file_get_contents($bootstrap);if(!is_string($src)||$src==='')return ['ok'=>false,'status'=>'bootstrap_unreadable','message'=>'app/bootstrap.php could not be read.'];if(strpos($src,"require_once __DIR__.'/public_runtime_v1101.php'")!==false)return ['ok'=>true,'status'=>'already_installed','message'=>'Active public runtime is already installed.'];if(!is_writable($bootstrap))return ['ok'=>false,'status'=>'bootstrap_not_writable','message'=>'app/bootstrap.php is not writable by PHP.'];$line="\n/* {$marker} */\nrequire_once __DIR__.'/public_runtime_v1101.php';\n";if(preg_match('/declare\s*\(\s*strict_types\s*=\s*1\s*\)\s*;/',$src,$m,PREG_OFFSET_CAPTURE)){$end=$m[0][1]+strlen($m[0][0]);$patched=substr($src,0,$end).$line.substr($src,$end);}else{$p=strpos($src,'<?php');if($p===false)return ['ok'=>false,'status'=>'bootstrap_format','message'=>'Unexpected app/bootstrap.php format.'];$end=$p+5;$patched=substr($src,0,$end).$line.substr($src,$end);}$dir=$root.'/storage/runtime_backups';if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))return ['ok'=>false,'status'=>'backup_dir','message'=>'Could not create storage/runtime_backups.'];$backup=$dir.'/bootstrap.php.pre-v1101.'.date('Ymd-His').'.bak';if(@file_put_contents($backup,$src,LOCK_EX)===false)return ['ok'=>false,'status'=>'backup_failed','message'=>'Could not create bootstrap backup. No changes made.'];$tmp=$bootstrap.'.v1101.tmp';if(@file_put_contents($tmp,$patched,LOCK_EX)===false){@unlink($tmp);return ['ok'=>false,'status'=>'write_failed','message'=>'Could not write temporary bootstrap patch.'];}@chmod($tmp,fileperms($bootstrap)&0777);if(!@rename($tmp,$bootstrap)){@unlink($tmp);return ['ok'=>false,'status'=>'rename_failed','message'=>'Could not activate public runtime patch.'];}return ['ok'=>true,'status'=>'installed','message'=>'Active landing/public runtime installed without replacing the current index.php.','backup'=>$backup];}
function sk1101_public_runtime_status(): array {$root=dirname(__DIR__);$bootstrap=$root.'/app/bootstrap.php';$src=is_file($bootstrap)?(string)@file_get_contents($bootstrap):'';return ['installed'=>strpos($src,"require_once __DIR__.'/public_runtime_v1101.php'")!==false,'bootstrap'=>$bootstrap,'writable'=>is_writable($bootstrap),'runtime_file'=>is_file($root.'/app/public_runtime_v1101.php')];}
